// The condition keys that take a value. They return a plain string, so wrap
// them in policy.Key when a condition wants a policy.ConditionKey.
func ConditionKeyCurrentCustomerMetadataPropertiesFor(value string) string {
	return "sagemaker:CurrentCustomerMetadataProperties/" + value
}

func ConditionKeyCustomerMetadataPropertiesFor(value string) string {
	return "sagemaker:CustomerMetadataProperties/" + value
}

func ConditionKeyResourceTagFor(value string) string { return "sagemaker:ResourceTag/" + value }

func ConditionKeySearchVisibilityConditionFor(value string) string {
	return "sagemaker:SearchVisibilityCondition/" + value
}
